window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1c9a3896bc5a6220"]={"versions": [{"id": "FIG-1c9a3896bc5a6220", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Baum (Feature-Oriented Domain Analysis – FODA / AUTOSAR Feature Modeling Notation).</li>\n<li><strong>Technischer Zweck:</strong> Strukturelle Dekomposition und Variabilitätsabbildung des Foundation-Features <code>FO_TR_FEAT_00199</code> („V2X“ – Vehicle-to-Everything Communication) in standardisierte, regional gebundene Ausprägungen.</li>\n<li><strong>Architektur-Einordnung:</strong> Verortung auf Foundation-Ebene (<code>FO_TR</code>), plattformübergreifend gültig als funktionale Anforderung für die Classic Platform (CP-BSW) und Adaptive Platform (AP-Clusters). Definiert die Systemgrenzen für V2X-Protokollstapel, Facilities-Layer, GeoNetworking/Routing und Security-Subsysteme.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzel-Feature (Parent):</strong></li>\n<li><code>FO_TR_FEAT_00199</code> (<code>V2X</code>): Abstraktes Dach-Feature für V2X-Konnektivität (Fahrzeug-zu-Fahrzeug, Fahrzeug-zu-Infrastruktur).</li>\n<li><strong>Sub-Features (Children):</strong></li>\n<li><code>FO_TR_FEAT_00200</code> (<code>V2X_China</code>): Konkretisierung für den chinesischen Markt (Profile basierend auf C-V2X PC5 Mode 4 direct communication, C-SAE/CSIC-Nachrichtenformaten wie BSM/RSM/MAP/SPaT und GB/T-Normen).</li>\n<li><code>FO_TR_FEAT_00201</code> (<code>V2X_Europe</code>): Konkretisierung für den europäischen Markt (Profile basierend auf ETSI TC ITS, GeoNetworking/BTP nach ETSI EN 302 636, CAM/DENM nach ETSI EN 302 637-2/-3 via ITS-G5/802.11p oder LTE-V2X).</li>\n<li><strong>Kanten-Semantik & Variabilität:</strong></li>\n<li>Beziehung: Top-Down-Dekomposition via gerichteter Kanten.</li>\n<li>Dekoration: Kanten enden am Zielknoten in einem <strong>ungefüllten/hohlen Kreis</strong>. Dies spezifiziert normative <strong>optionale Sub-Features</strong> (<em>Optional Features</em>).</li>\n<li>Kardinalität: $[0..1]$ bzw. $[0..n]$ bezogen auf das Parent-Feature (ein V2X-System kann je nach Ziel-ECU markt-exklusiv oder für Multi-Region-Betrieb beide Profile selektieren).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend:</strong> Rein statisches Variabilitäts- und Taxonomie-Diagramm; keine Abbildung von Zeitverläufen, Zuständen oder Laufzeit-Interaktionen.</li>\n<li><strong>Laufzeit-Äquivalent:</strong> Die im Diagramm selektierten Features determinieren zur BSW-Laufzeit die zyklischen Tasks (<code>*_MainFunction</code>) und Event-Routen der nachgelagerten Module (z. B. <code>V2xFac</code>, <code>V2xM</code>, GeoNet-Router) über den BSW-Scheduler (SchM).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Auswahl & Footprint:</strong></li>\n<li>Das Diagramm steuert die Feature-Selektion im Variantenmanagement. Je nach Build-Target wird nur der regionsspezifische Protokollstapel kompiliert, um RAM-/Flash-Overhead auf Microcontrollern zu minimieren.</li>\n<li><strong>Protokoll- & Treiber-Konsequenzen:</strong></li>\n<li><strong>Bei Auswahl <code>V2X_China</code> (<code>FO_TR_FEAT_00200</code>):</strong> Erfordert Krypto-Unterstützung für chinesische Algorithmen (SM2, SM3, SM4) im Crypto Stack (CSM/Crypto Driver) sowie C-SAE-spezifische PDU-Handler/Serialisierer. Anbindung primär an C-V2X Direct Communication (PC5-Interface).</li>\n<li><strong>Bei Auswahl <code>V2X_Europe</code> (<code>FO_TR_FEAT_00201</code>):</strong> Erfordert ETSI TS 103 097 / IEEE 1609.2 Zertifikatsverwaltung und PKI-Validierung (ECDSA NIST P-256 / Brainpool), GeoNetworking-Router-Modul und ETSI-Facilities (CAM/DENM-Generierung).</li>\n<li><strong>Applikations-Schnittstelle (SW-C-Ebene):</strong></li>\n<li>SW-Cs für V2X-Fahrerassistenzfunktionen müssen entweder gegen regionsunabhängige generische V2X-Ports (z. B. normierte Trajektorien-/Warnungs-Interfaces) anbinden oder separate Schnittstellenadapter für die stark divergierenden Datensätze (CAM vs. BSM) vorhalten.</li>\n</ul>"}, {"id": "FIG-12ac57e55ade20be", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Baum (Feature-Oriented Domain Analysis – FODA / AUTOSAR Feature Modeling Notation).</li>\n<li><strong>Technischer Zweck:</strong> Strukturelle Dekomposition und Variabilitätsabbildung des Foundation-Features <code>FO_TR_FEAT_00199</code> („V2X“ – Vehicle-to-Everything Communication) in standardisierte, regional gebundene Ausprägungen.</li>\n<li><strong>Architektur-Einordnung:</strong> Verortung auf Foundation-Ebene (<code>FO_TR</code>), plattformübergreifend gültig als funktionale Anforderung für die Classic Platform (CP-BSW) und Adaptive Platform (AP-Clusters). Definiert die Systemgrenzen für V2X-Protokollstapel, Facilities-Layer, GeoNetworking/Routing und Security-Subsysteme.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzel-Feature (Parent):</strong></li>\n<li><code>FO_TR_FEAT_00199</code> (<code>V2X</code>): Abstraktes Dach-Feature für V2X-Konnektivität (Fahrzeug-zu-Fahrzeug, Fahrzeug-zu-Infrastruktur).</li>\n<li><strong>Sub-Features (Children):</strong></li>\n<li><code>FO_TR_FEAT_00200</code> (<code>V2X_China</code>): Konkretisierung für den chinesischen Markt (Profile basierend auf C-V2X PC5 Mode 4 direct communication, C-SAE/CSIC-Nachrichtenformaten wie BSM/RSM/MAP/SPaT und GB/T-Normen).</li>\n<li><code>FO_TR_FEAT_00201</code> (<code>V2X_Europe</code>): Konkretisierung für den europäischen Markt (Profile basierend auf ETSI TC ITS, GeoNetworking/BTP nach ETSI EN 302 636, CAM/DENM nach ETSI EN 302 637-2/-3 via ITS-G5/802.11p oder LTE-V2X).</li>\n<li><strong>Kanten-Semantik & Variabilität:</strong></li>\n<li>Beziehung: Top-Down-Dekomposition via gerichteter Kanten.</li>\n<li>Dekoration: Kanten enden am Zielknoten in einem <strong>ungefüllten/hohlen Kreis</strong>. Dies spezifiziert normative <strong>optionale Sub-Features</strong> (<em>Optional Features</em>).</li>\n<li>Kardinalität: $[0..1]$ bzw. $[0..n]$ bezogen auf das Parent-Feature (ein V2X-System kann je nach Ziel-ECU markt-exklusiv oder für Multi-Region-Betrieb beide Profile selektieren).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend:</strong> Rein statisches Variabilitäts- und Taxonomie-Diagramm; keine Abbildung von Zeitverläufen, Zuständen oder Laufzeit-Interaktionen.</li>\n<li><strong>Laufzeit-Äquivalent:</strong> Die im Diagramm selektierten Features determinieren zur BSW-Laufzeit die zyklischen Tasks (<code>*_MainFunction</code>) und Event-Routen der nachgelagerten Module (z. B. <code>V2xFac</code>, <code>V2xM</code>, GeoNet-Router) über den BSW-Scheduler (SchM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Auswahl & Footprint:</strong></li>\n<li>Das Diagramm steuert die Feature-Selektion im Variantenmanagement. Je nach Build-Target wird nur der regionsspezifische Protokollstapel kompiliert, um RAM-/Flash-Overhead auf Microcontrollern zu minimieren.</li>\n<li><strong>Protokoll- & Treiber-Konsequenzen:</strong></li>\n<li><strong>Bei Auswahl <code>V2X_China</code> (<code>FO_TR_FEAT_00200</code>):</strong> Erfordert Krypto-Unterstützung für chinesische Algorithmen (SM2, SM3, SM4) im Crypto Stack (CSM/Crypto Driver) sowie C-SAE-spezifische PDU-Handler/Serialisierer. Anbindung primär an C-V2X Direct Communication (PC5-Interface).</li>\n<li><strong>Bei Auswahl <code>V2X_Europe</code> (<code>FO_TR_FEAT_00201</code>):</strong> Erfordert ETSI TS 103 097 / IEEE 1609.2 Zertifikatsverwaltung und PKI-Validierung (ECDSA NIST P-256 / Brainpool), GeoNetworking-Router-Modul und ETSI-Facilities (CAM/DENM-Generierung).</li>\n<li><strong>Applikations-Schnittstelle (SW-C-Ebene):</strong></li>\n<li>SW-Cs für V2X-Fahrerassistenzfunktionen müssen entweder gegen regionsunabhängige generische V2X-Ports (z. B. normierte Trajektorien-/Warnungs-Interfaces) anbinden oder separate Schnittstellenadapter für die stark divergierenden Datensätze (CAM vs. BSM) vorhalten.</li>\n</ul>"}], "trans": [{"from": "FIG-1c9a3896bc5a6220", "to": "FIG-12ac57e55ade20be", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
